-- Recovered from the linked project's Supabase migration history.

-- Drop a Finger playable V2: 362 active cards, 2,338 preserved archived cards.
begin;

create temporary table decked_drop_a_finger_v2_active(item_id uuid primary key,category_id text not null,sort_order integer not null,body text not null,metadata jsonb not null,revised boolean not null) on commit drop;


do $$ declare matched integer; begin select count(*) into matched from public.content_items item join decked_drop_a_finger_v2_active selected on selected.item_id=item.id where item.game_id='finger-down'; if matched<>362 then raise exception 'Drop a Finger V2 inventory mismatch: expected 362 IDs, found %',matched; end if; end $$;

update public.content_items set lifecycle_status='archived',updated_at=now() where game_id='finger-down';

update public.content_items item set lifecycle_status='active',updated_at=now() from decked_drop_a_finger_v2_active selected where item.id=selected.item_id and item.game_id='finger-down';

update public.content_item_categories set enabled=false where game_id='finger-down';


create temporary table decked_drop_a_finger_v2_revisions on commit drop as select selected.*,item.current_version+1 next_version from decked_drop_a_finger_v2_active selected join public.content_items item on item.id=selected.item_id where selected.revised;

update public.content_item_versions version set editorial_status='superseded' from decked_drop_a_finger_v2_revisions revised where version.item_id=revised.item_id and version.version=(select published_version from public.content_items where id=revised.item_id);


update public.content_items item set current_version=revised.next_version,published_version=revised.next_version,updated_at=now() from decked_drop_a_finger_v2_revisions revised where item.id=revised.item_id;

update public.content_item_versions version set metadata=coalesce(version.metadata,'{}'::jsonb)||selected.metadata from decked_drop_a_finger_v2_active selected join public.content_items item on item.id=selected.item_id where not selected.revised and version.item_id=item.id and version.version=item.published_version;

update public.content_releases set status='superseded' where game_id='finger-down' and status='published';


delete from public.content_release_items where release_id='2b18ecb1-dd56-5da3-b580-8dbfca92f767'::uuid;


commit;
